-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["fa01b212f5c1f02c"] = { "Ai superstiti degli orchi, laceri e dispersi, non restò altro che fuggire verso l'ultimo bastione ancora in piedi del potere orchesco: il Portale Oscuro.\n\nTuralyon e i suoi guerrieri inseguirono gli orchi rimasti attraverso la putrida ⟦Swamp of Sorrows=Palude del Dolore⟧ e nelle corrotte ⟦Blasted Lands=Terre Devastate⟧, dove si ergeva il Portale Oscuro. Lì, ai piedi del colossale portale, l'orda in rotta e la tenace ⟦Alliance=Alleanza⟧ si scontrarono in quella che sarebbe stata l'ultima e più sanguinosa battaglia della Seconda Guerra.", "." },
  ["fa04e6adc61f5a1b"] = { "La società umana di Arathor crebbe e prosperò, ma Thoradin, temendo che il suo regno si frantumasse se si fosse esteso troppo, mantenne Strom al centro dell'impero di Arathor. Dopo molti anni di pace, di crescita e di commerci, il possente Thoradin morì di vecchiaia, lasciando le giovani generazioni di Arathor libere di espandere l'impero oltre le terre di Strom.", "." },
  ["fa2003540902ff7c"] = { "Ma perché lo dico? Lo faccio per dare credito a ciò che sto per scrivere, perché queste parole sono uscite dalle labbra di Kegan, e spero che i miei colleghi, leggendo questo diario, capiscano perché credo a ciò che ha detto:\n\n\"I resti degli Dei Antichi indugiano ancora nelle profonde cavità del mondo. Nuove forze cercano di imbrigliare quell'antico potere, e chi ci riuscirà avrà un'arma terribile contro i propri nemici.\"", "." },
  ["fa43cf1e9723add5"] = { "Per simboleggiare la rinascita del suo popolo, Thrall tornò alla fortezza di Blackmoore, Durnholde, e pose fine in modo decisivo ai piani del suo ex padrone assediando i campi di internamento. Questa vittoria non fu senza prezzo: durante la liberazione di uno dei campi, Doomhammer cadde in battaglia.", "." },
  ["fa6df2374a282dfc"] = { "Spero che questa lettera ti trovi in buona salute, {class}. Lo dico con grande orgoglio, perché non sono in molti a poter professare una fede così profonda e, al tempo stesso, sapere di essere tra i protettori più scelti di Azeroth.\n\nRicorda sempre, prima di ogni altra cosa, che è tuo dovere scendere in battaglia contro chi cerca di nuocere al nostro mondo e di portare la corruzione nelle nostre case.\n\nPer ora mi è stata affidata la responsabilità del tuo addestramento. Quando te la senti, cercami dentro l'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.\n\n-Fratello Sammuel, istruttore dei paladini", "." },
  ["fac5d66b10f96ba6"] = { "Bada a non ignorare le mie parole, {name}. Questo è il tempo dei sotterfugi e degli inganni in tutte le nazioni... persino nella nostra grande ⟦Undercity=Sepulcra⟧. Tutti i fedeli di Sylvanas lavorano per creare una nuova era, un'era sotto il controllo dei Reietti. E anche se non possediamo poteri magici, né impugneremo le armi lungo i nostri confini, abbiamo comunque un ruolo da svolgere.\n\nCercami nella locanda di ⟦Deathknell=Albamorta⟧. Ne parleremo meglio allora.\n\n-David Trias, istruttore dei ladri", "." },
  ["fad9a9de972623f1"] = { "⟦Galvanized Horn=Corno Galvanizzato⟧:\n\nLa resistenza del raro corno galvanizzato è il cardine dell'intera armatura che creerò, perciò anche questo va procurato.\n\nSi può ottenere dalla rara matriarca delle chimere nella ⟦Charred Vale=Valle Bruciata⟧.", "." },
  ["faf50f0a266d742e"] = { "Oltre a uccidere Dartol, i mezzorsi divisero la verga in tre parti perché non potesse più essere usata contro di loro. Non è stato facile, ma ho una buona idea di dove siano state collocate tutte e tre le parti.\n\nLa gemma\nLa prima parte della verga, una gemma luminosa, fu nascosta in un santuario nel nord-ovest di ⟦Ashenvale=Valtetra⟧. Ora credo che questo santuario siano le rovine al centro del ⟦Lake Falathim=Lago Falathim⟧. Le ⟦Sentinels=Sentinelle⟧ mi dicono che adesso vi abitano i murloc.", "." },
})
